#pragma once
/**
 * @file NetworkRunArtifactsRunEnd.hpp
 * @brief Run-end reports of the run's artifacts: the trace streams' close, the run manifest's complete record, the flag-rate and run-summary CSVs.
 *
 * The run-end reports defined in NetworkRunArtifactsRunEnd.cpp; each is a row of kNetworkRunEndReports
 * (filter/NetworkRunEnd.hpp).
 */

namespace GnssProcessor {

// ---- Run-end reports (card NOM step TD1b; generated by scripts/nom_td_cut.py) ----

struct NetworkRunEndView;

/**
 * @brief Run-end report: trace close: the estimability RUN row, then every trace stream closed.
 *
 * Writes the RUN row of network_estimability.csv (the rank-gate tolerance and the run's
 * gate totals; a no-op with the trace off) and closes every trace stream. Prints
 * nothing. It is the table's first row: after it no report may write to a trace stream,
 * which drops a write silently once closed.
 *
 * Gate: prints always.
 *
 * @param v The run at its end (filter/NetworkRunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkTraceCloseRunEnd(const NetworkRunEndView& v);

/**
 * @brief Run-end report: the run manifest's complete record.
 *
 * Appends the run manifest's `complete` record, which stays the manifest's last line;
 * prints nothing.
 *
 * Gate: prints always.
 *
 * @param v The run at its end (filter/NetworkRunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkRunManifestCompleteRunEnd(const NetworkRunEndView& v);

/**
 * @brief Run-end report: flag rates, the run summary and the shared-product line.
 *
 * The flag-rate summary and the run-summary CSV (network.trace_flag_rates): first the
 * IF-TD reference arm's opportunities and flags are summed from the stations into a
 * local the writer takes (it was summed into the run context); then the shared-product
 * line, which scripts/pc_gate_verdict.py reads as the run's done marker.
 *
 * Gate: prints always.
 *
 * @param v The run at its end (filter/NetworkRunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkRunSummaryRunEnd(const NetworkRunEndView& v);

// ---- End of the run-end reports ----

} // namespace GnssProcessor
